// EXISTING IMPLEMENTATION (551 lines) - Key sections for hybrid search:

// 1. Orama index creation and configuration
export async function createOramaIndex(
  instanceId: string,
  embeddings: Embeddings
): Promise<Orama<typeof schema>> {
  const orama = await create({
    schema,
    id: instanceId,
  });
  return orama;
}

// 2. Vector search (already implemented)
export async function vectorSearch(
  orama: Orama<typeof schema>,
  query: string,
  limit: number = 10
): Promise<VectorSearchResult[]> {
  const embeddings = await loadEmbeddings();
  const vector = await embeddings.embed(query);
  const results = await search(orama, {
    mode: 'vector',
    term: vector,
    limit,
  });
  return results;
}

// 3. Fulltext search (needs hybrid integration)
export async function fulltextSearch(
  orama: Orama<typeof schema>,
  query: string,
  limit: number = 10
): Promise<FulltextSearchResult[]> {
  const results = await search(orama, {
    mode: 'fulltext',
    term: query,
    limit,
  });
  return results;
}

// 4. Schema definition
const schema = {
  id: 'string',
  documentId: 'string',
  content: 'string',
  embedding: 'vector[384]',
  metadata: 'object',
  createdAt: 'number',
  updatedAt: 'number',
};

// EXISTING RAG STORE - State management for RAG operations:

interface RAGState {
  indexes: Map<string, Orama<typeof schema>>;
  activeIndex: string | null;
  searchResults: SearchResult[];
  isSearching: boolean;
  lastSearchQuery: string;
}

// Actions that will use hybrid search:
- search(query: string, options?: SearchOptions)
- indexDocument(document: SourceDocument)
- deleteDocument(documentId: string)
- clearIndex()

// EXISTING EMBEDDING WORKER - For generating embeddings:

// Uses Transformers.js (CLIP) for 384-dimensional embeddings
// Web Worker pattern for non-blocking embedding generation
// Methods:
- embed(text: string): Promise<number[]>
- embedBatch(texts: string[]): Promise<number[][]>
